// bundle/app.js — summarise the current note with the user's preferred model.
try {
  const reply = await anna.llm.complete({
    systemPrompt: "You are a concise summariser. Output 1–2 sentences.",
    messages: [
      { role: "user", content: noteBody.value.slice(0, 8000) },
    ],
    maxTokens: 256,
    temperature: 0.3,
    modelPreferences: { intelligencePriority: 0.4, speedPriority: 0.6 },
  }, { timeoutMs: 60_000 });

  render(reply.content.text);
  log(`model=${reply.model} tokens=${reply.usage.totalTokens} quota=${reply._meta.quotaConsumed}`);
} catch (e) {
  switch (e.code) {
    case "APP_NOT_GRANTED":      setStatus("User hasn't granted LLM access to this app"); break;
    case "APP_QUOTA_EXCEEDED":   setStatus("Out of quota — try again next cycle");        break;
    case "APP_INVALID_REQUEST":  setStatus(`Bad request: ${e.message}`);                  break;
    case "APP_PROVIDER_ERROR":   setStatus("Model provider error — please retry");        break;
    default:                     throw e;
  }
}

const stream = await anna.llm.stream({
  messages: [{ role: 'user', content: 'Write a haiku about the sea.' }],
  maxTokens: 200
});
let text = '';
for await (const frame of stream) {
  if (frame.event === 'model_token') {
    text += frame.text;
    output.textContent = text;      // live token-by-token render
  } else if (frame.event === 'complete') {
    console.log(frame.model, frame.usage, frame._meta?.quotaConsumed);
  }
}
